<script setup>
import { computed,onMounted,ref } from 'vue'; import DataTable from 'primevue/datatable'; import Column from 'primevue/column'; import InputText from 'primevue/inputtext'; import Button from 'primevue/button'; import Dialog from 'primevue/dialog'; import InputNumber from 'primevue/inputnumber'; import Select from 'primevue/select'; import DatePicker from 'primevue/datepicker'; import Message from 'primevue/message'; import StatusTag from '../../components/StatusTag.vue'; import LoadingState from '../../components/LoadingState.vue'; import EmptyState from '../../components/EmptyState.vue'; import api,{errorMessage} from '../../services/api'
const rows=ref([]),loading=ref(true),error=ref(''),query=ref(''),dialog=ref(false),saving=ref(false),formError=ref('');const form=ref({userId:null,apartmentId:null,residentType:'OWNER',phone:'',moveInDate:null});const types=['OWNER','TENANT','FAMILY_MEMBER'];const filtered=computed(()=>rows.value.filter(r=>`${r.fullName} ${r.email} ${r.apartment?.unitNumber}`.toLowerCase().includes(query.value.toLowerCase())));const load=async()=>{loading.value=true;try{rows.value=(await api.get('/management/residents')).data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}};const open=()=>{form.value={userId:null,apartmentId:null,residentType:'OWNER',phone:'',moveInDate:null};formError.value='';dialog.value=true};const submit=async()=>{if(!form.value.userId||!form.value.apartmentId){formError.value='Nhập User ID và Apartment ID.';return}saving.value=true;try{await api.post('/management/residents',{...form.value,moveInDate:form.value.moveInDate?.toISOString().slice(0,10)||null});dialog.value=false;await load()}catch(e){formError.value=errorMessage(e)}finally{saving.value=false}};onMounted(load)
</script>
<template><div class="page-heading"><div><h1>Cư dân</h1><p>Danh sách hồ sơ cư dân đang quản lý.</p></div><Button label="Tạo hồ sơ" icon="pi pi-plus" @click="open" /></div><div class="content-card"><div class="toolbar"><InputText v-model="query" placeholder="Tìm cư dân..." /></div><LoadingState v-if="loading" /><div v-else-if="error" class="error-panel">{{error}}</div><EmptyState v-else-if="!filtered.length" title="Chưa có cư dân" /><DataTable v-else :value="filtered" paginator :rows="10" class="data-table" responsive-layout="scroll"><Column field="fullName" header="Họ tên" /><Column field="email" header="Email" /><Column header="Căn hộ"><template #body="{data}">{{data.apartment?.buildingCode}} · {{data.apartment?.unitNumber}}</template></Column><Column field="phone" header="Điện thoại" /><Column header="Loại"><template #body="{data}"><StatusTag :value="data.residentType" /></template></Column><Column header="Trạng thái"><template #body="{data}"><StatusTag :value="data.active?'ACTIVE':'CANCELLED'" /></template></Column></DataTable></div><Dialog v-model:visible="dialog" modal header="Tạo hồ sơ cư dân" :style="{width:'min(38rem,94vw)'}"><Message v-if="formError" severity="error">{{formError}}</Message><div class="form-grid"><div class="field"><label>User ID</label><InputNumber v-model="form.userId" :use-grouping="false" /></div><div class="field"><label>Apartment ID</label><InputNumber v-model="form.apartmentId" :use-grouping="false" /></div><div class="field"><label>Loại cư dân</label><Select v-model="form.residentType" :options="types" /></div><div class="field"><label>Ngày vào ở</label><DatePicker v-model="form.moveInDate" date-format="dd/mm/yy" /></div><div class="field full"><label>Điện thoại</label><InputText v-model.trim="form.phone" /></div></div><div class="dialog-footer"><Button label="Hủy" text @click="dialog=false"/><Button label="Tạo hồ sơ" :loading="saving" @click="submit"/></div></Dialog></template>
